151	void OnePort::setupSCPI()
152	{
153	    add(new SCPICommand("FILE", [=](QStringList params) -> QString {
154	        if(params.size() < 1) {
155	            return SCPI::getResultName(SCPI::Result::Error);
156	        }
157	        try {
158	            auto ts = Touchstone::fromFile(params[0].toStdString());
159	            unsigned long long index = 0;
160	            if(params.size() == 2) {
161	                if(!SCPI::paramToULongLong(params, 1, index)) {
162	                    return SCPI::getResultName(SCPI::Result::Error);
163	                }
164	            }
165	            setMeasurement(ts, index-1);
166	            return SCPI::getResultName(SCPI::Result::Empty);
167	        } catch(const std::exception& e) {
168	            // failed to load file
169	            return SCPI::getResultName(SCPI::Result::Error);
170	        }
171	    }, nullptr, false));
172	    Virtual::setupSCPI();
173	}
