182	std::complex<double> Open::toS11(double freq)
183	{
184	    if(touchstone) {
185	        return touchstone->interpolate(freq).S[0];
186	    } else {
187	        // calculate fringing capacitance for open
188	        double Cfringing = C0 * 1e-15 + C1 * 1e-27 * freq + C2 * 1e-36 * pow(freq, 2) + C3 * 1e-45 * pow(freq, 3);
189	        // convert to impedance
190	        complex<double> open;
191	        if (Cfringing == 0) {
192	            // special case to avoid issues with infinity
193	            open = complex<double>(1.0, 0);
194	        } else {
195	            auto imp_open = complex<double>(0, -1.0 / (freq * 2 * M_PI * Cfringing));
196	            open = (imp_open - complex<double>(50.0)) / (imp_open + complex<double>(50.0));
197	        }
198	        return Util::addTransmissionLine(open, Z0, delay*1e-12, loss*1e9, freq);
199	    }
200	}
