442	    Cfirst = true;
443	    setupSCPI();
444	}
445	
446	std::complex<double> Load::toS11(double freq)
447	{
448	    if(touchstone) {
449	        return touchstone->interpolate(freq).S[0];
450	    } else {
451	        auto imp_load = complex<double>(resistance, 0);
452	        if (Cfirst) {
453	            // C is the first parameter starting from the VNA port. But the load is modeled here starting from
454	            // the other end, so we need to start with the inductor
455	            imp_load += complex<double>(0, freq * 2 * M_PI * Lseries);
456	        }
457	        // Add parallel capacitor to impedance
458	        if(Cparallel > 0) {
459	            auto imp_C = complex<double>(0, -1.0 / (freq * 2 * M_PI * Cparallel));
460	            imp_load = (imp_load * imp_C) / (imp_load + imp_C);
461	        }
462	        if (!Cfirst) {
463	            // inductor not added yet, do so now
464	            imp_load += complex<double>(0, freq * 2 * M_PI * Lseries);
465	        }
466	        complex<double> load = (imp_load - complex<double>(50.0)) / (imp_load + complex<double>(50.0));
467	        return Util::addTransmissionLine(load, Z0, delay*1e-12, loss*1e9, freq);
468	    }
469	}
