482	    ui->Z0->setPrecision(4);
483	    ui->Z0->setValue(Z0);
484	    ui->delay->setValue(delay);
485	    ui->loss->setValue(loss);
486	    ui->parC->setUnit("F");
487	    ui->parC->setPrefixes("pnum ");
488	    ui->parC->setPrecision(4);
489	    ui->parC->setValue(Cparallel);
490	    ui->serL->setUnit("H");
491	    ui->serL->setPrefixes("num ");
492	    ui->serL->setPrecision(4);
493	    ui->serL->setValue(Lseries);
494	
495	    if(Cfirst) {
496	        ui->C_first->setChecked(true);
497	    } else {
498	        ui->L_first->setChecked(true);
499	    }
500	
501	    auto updateMeasurementLabel = [=](){
502	        QString label;
503	        if(touchstone) {
504	            label = QString::number(touchstone->points())+" points from "+Unit::ToString(touchstone->minFreq(), "Hz", " kMG")+" to "+Unit::ToString(touchstone->maxFreq(), "Hz", " kMG");
505	        } else {
506	            label = "No measurements stored yet";
507	        }
508	        ui->measurementLabel->setText(label);
509	    };
510	
511	    QObject::connect(ui->coefficients, &QRadioButton::toggled, [=](bool checked) {
512	        if(checked) {
513	            clearMeasurement();
514	        }
515	        ui->stackedWidget->setCurrentIndex(checked ? 0 : 1);
516	    });
517	    QObject::connect(ui->measurement, &QRadioButton::toggled, [=](bool checked) {
518	        updateMeasurementLabel();
519	        ui->stackedWidget->setCurrentIndex(checked ? 1 : 0);
520	    });
521	
522	    QObject::connect(ui->touchstoneImport, &TouchstoneImport::statusChanged, ui->updateFile, &QPushButton::setEnabled);
523	
524	    ui->touchstoneImport->setPorts(1);
525	    if(touchstone) {
