665	Sparam Through::toSparam(double freq)
666	{
667	    if(touchstone) {
668	        auto interp = touchstone->interpolate(freq).S;
669	        return Sparam(interp[0], interp[1], interp[2], interp[3]);
670	    } else {
671	        // calculate effect of through
672	        // nomenclature and formulas from https://loco.lab.asu.edu/loco-memos/edges_reports/report_20130807.pdf
673	        auto w = 2.0 * M_PI * freq;
674	        auto f_sqrt = sqrt(freq / 1e9);
675	        auto offset_impedance = Z0;         // lossless characteristic impedance
676	        auto offset_loss = loss * 1e9;
677	        auto offset_delay = delay * 1e-12;
678	
679	        auto Z_c = std::complex<double>(offset_impedance + (offset_loss / (2*w)) * f_sqrt, -(offset_loss / (2*w)) * f_sqrt);
680	        auto gamma_l = std::complex<double>(offset_loss*offset_delay/(2*offset_impedance)*f_sqrt, w*offset_delay+offset_loss*offset_delay/(2*offset_impedance)*f_sqrt);
681	        auto p = exp(-gamma_l); // propagation factor
682	
683	        auto Z_r = std::complex<double>(50.0);
684	        auto Gamma = (Z_c - Z_r) / (Z_c + Z_r);
685	
686	        // S-parameter of a transmission line, see e.g. "Specifying Calibration Standards and Kits for Keysight Vector Network Analyzers"
687	        // Keysight application note equations (6) and (7)
688	        auto Sxx = Gamma * (1.0 - p*p) / (1.0 - p*p*Gamma*Gamma);
689	        auto Sxy = p * (1.0 - Gamma*Gamma) / (1.0 - p*p*Gamma*Gamma);
690	        return Sparam(Sxx, Sxy, Sxy, Sxx);
691	    }
692	}
