23	    for(auto e : descr) {
24	        e.var.setValue(e.def);
25	    }
26	
27	    add(new SCPICommand("MANufacturer", [=](QStringList params) -> QString {
28	        if(params.size() != 1 ) {
29	            // no new value given
30	            return SCPI::getResultName(SCPI::Result::Error);
31	        }
32	        manufacturer = params[0];
33	        return SCPI::getResultName(SCPI::Result::Empty);
34	    }, [=](QStringList) -> QString {
35	        return manufacturer;
36	    }, false));
37	    add(new SCPICommand("SERial", [=](QStringList params) -> QString {
38	        if(params.size() != 1 ) {
39	            // no new value given
40	            return SCPI::getResultName(SCPI::Result::Error);
41	        }
42	        serialnumber = params[0];
43	        return SCPI::getResultName(SCPI::Result::Empty);
44	    }, [=](QStringList) -> QString {
45	        return serialnumber;
46	    }, false));
47	    add(new SCPICommand("DESCription", [=](QStringList params) -> QString {
48	        if(params.size() != 1 ) {
49	            // no new value given
50	            return SCPI::getResultName(SCPI::Result::Error);
51	        }
52	        description = params[0];
53	        return SCPI::getResultName(SCPI::Result::Empty);
54	    }, [=](QStringList) -> QString {
55	        return description;
56	    }, false));
57	    add(new SCPICommand("FILEname", nullptr, [=](QStringList) -> QString {
58	        return filename;
59	    }));
60	    add(new SCPICommand("SAVE", [=](QStringList params) -> QString {
61	        if(params.size() != 1 ) {
62	            // no filename given or no calibration active
63	            return SCPI::getResultName(SCPI::Result::Error);
64	        }
65	        toFile(params[0]);
66	        return SCPI::getResultName(SCPI::Result::Empty);
67	    }, nullptr, false));
68	    add(new SCPICommand("LOAD", nullptr, [=](QStringList params) -> QString {
69	        if(params.size() != 1) {
70	            // no filename given or no calibration active
71	            return SCPI::getResultName(SCPI::Result::False);
72	        }
73	        if(this->fromFile(params[0])) {
74	            return SCPI::getResultName(SCPI::Result::True);
75	        } else {
76	            return SCPI::getResultName(SCPI::Result::False);
77	        }
78	    }, false));
79	    scpi_std.add(new SCPICommand("CLEAR", [=](QStringList params) -> QString {
80	        Q_UNUSED(params);
81	        setIdealDefault();
82	        return SCPI::getResultName(SCPI::Result::Empty);
83	    }, nullptr));
84	    scpi_std.add(new SCPICommand("NUMber", nullptr, [=](QStringList params) -> QString {
85	        Q_UNUSED(params);
86	        return QString::number(standards.size());
87	    }));
88	    scpi_std.add(new SCPICommand("NEW", [=](QStringList params) -> QString {
89	        if(params.size() != 2) {
90	            return SCPI::getResultName(SCPI::Result::Error);
91	        }
92	        auto type = CalStandard::Virtual::TypeFromString(params[0]);
93	        if(type == CalStandard::Virtual::Type::Last) {
94	            return SCPI::getResultName(SCPI::Result::Error);
95	        }
96	        auto s = CalStandard::Virtual::create(type);
97	        if(!s) {
98	            return SCPI::getResultName(SCPI::Result::Error);
99	        }
100	        s->setName(params[1]);
101	        addStandard(s);
102	        return SCPI::getResultName(SCPI::Result::Empty);
103	    }, nullptr, false));
104	    scpi_std.add(new SCPICommand("DELete", [=](QStringList params) -> QString {
105	        unsigned long long index;
106	        if(!SCPI::paramToULongLong(params, 0, index)) {
107	            return SCPI::getResultName(SCPI::Result::Error);
108	        }
109	        if(index < 1 || index > standards.size()) {
110	            return SCPI::getResultName(SCPI::Result::Error);
111	        }
112	        removeStandard(standards[index-1]);
113	        return SCPI::getResultName(SCPI::Result::Empty);
114	    }, nullptr));
115	    scpi_std.add(new SCPICommand("TYPE", nullptr, [=](QStringList params) -> QString {
116	        unsigned long long index = 0;
117	        if(!SCPI::paramToULongLong(params, 0, index)) {
118	            return SCPI::getResultName(SCPI::Result::Error);
119	        }
120	        if(index < 1 || index > standards.size()) {
121	            return SCPI::getResultName(SCPI::Result::Error);
122	        }
123	        return CalStandard::Virtual::TypeToString(standards[index-1]->getType()).replace(" ", "_");
124	    }));
125	    add(&scpi_std);
126	}
