478	{
479	    // check for ID collisions. This should never happen but would mess up further
480	    // usage of the standards. Better to catch this now and throw an error
481	    for(auto comp : standards) {
482	        if(comp->getID() == s->getID()) {
483	            // collision, do not add
484	            InformationBox::ShowError("Calibration standard ID collision", "New standard \""
485	                                      +s->getName()+"\" of type \""+CalStandard::Virtual::TypeToString(s->getType())
486	                                      +"\" has the same ID as already existing standard \""
487	                                      +comp->getName()+"\" of type \""+CalStandard::Virtual::TypeToString(comp->getType())
488	                                      +"\" (ID="+QString::number(s->getID())+"). It will be removed from the calibration kit");
489	            return;
490	        }
